create table public.cda_orc_dimensionamento(id uuid primary key default gen_random_uuid(),nome text not null,shows integer not null check(shows>0),publico integer not null check(publico>0),capacidade_loja numeric check(capacidade_loja>0),compradores_vendedor numeric check(compradores_vendedor>0),estoquistas_loja numeric check(estoquistas_loja>=0),apoio_loja numeric check(apoio_loja>=0),apoio_evento numeric check(apoio_evento>=0),valor_vendedor numeric check(valor_vendedor>=0),valor_estoquista numeric check(valor_estoquista>=0),valor_apoio numeric check(valor_apoio>=0),arredondamento text not null default 'cima' check(arredondamento in ('cima','proximo')),referencias jsonb not null,atualizado_em timestamptz not null default now());
alter table public.cda_orc_dimensionamento enable row level security;
grant select,insert,update on public.cda_orc_dimensionamento to authenticated;
revoke all on public.cda_orc_dimensionamento from anon;
create policy leitura on public.cda_orc_dimensionamento for select to authenticated using (exists(select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and (e.is_admin or 'orcamento_vendas'=any(e.projetos))));
create policy inclusao on public.cda_orc_dimensionamento for insert to authenticated with check (exists(select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and (e.is_admin or 'orcamento_vendas'=any(e.projetos))) and exists(select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and coalesce(e.permissao,'leitura_escrita')='leitura_escrita'));
create policy edicao on public.cda_orc_dimensionamento for update to authenticated using (exists(select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and (e.is_admin or 'orcamento_vendas'=any(e.projetos))) and exists(select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and coalesce(e.permissao,'leitura_escrita')='leitura_escrita')) with check (exists(select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and (e.is_admin or 'orcamento_vendas'=any(e.projetos))) and exists(select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and coalesce(e.permissao,'leitura_escrita')='leitura_escrita'));
